<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import type {StorageApi} from './api'
import type {Product,Category} from './types'
import {displayName} from '../shared-commerce/format'
import ProductBarcodeScanner from '../shared-commerce/barcode/ProductBarcodeScanner.vue'
import {useCustomerStorageText} from './customer/text'
const props=defineProps<{api:StorageApi;disabled:boolean}>(),emit=defineEmits<{choose:[Product];manual:[string];error:[unknown]}>(),{t,locale}=useCustomerStorageText()
const search=ref(''),category=ref(''),page=ref(0),items=ref<Product[]>([]),categories=ref<Category[]>([]),more=ref(false),loading=ref(false),scanOpen=ref(false),message=ref(''),scanning=ref(false)
let generation=0,scanGeneration=0
async function load(){const own=++generation;loading.value=true;items.value=[];more.value=false;try{const params=new URLSearchParams({query:search.value,categoryId:category.value,page:String(page.value)});if(!category.value)params.delete('categoryId');const data=await props.api.get<{items:Product[];categories:Category[];hasMore:boolean}>('/product-options?'+params);if(own!==generation)return;items.value=data.items??[];categories.value=data.categories??[];more.value=data.hasMore===true}catch(e){if(own===generation)emit('error',e)}finally{if(own===generation)loading.value=false}}
watch([search,category],()=>{page.value=0;void load()})
watch(page,()=>void load())
watch(()=>props.api.base,()=>{generation++;scanGeneration++;scanning.value=false;search.value='';category.value='';page.value=0;message.value='';scanOpen.value=false;void load()},{immediate:true})
onUnmounted(()=>{generation++;scanGeneration++})
async function barcode(code:string){if(props.disabled||scanning.value)return;const own=++scanGeneration;scanning.value=true;message.value='';try{const data=await props.api.get<{items:Product[]}>('/product-options?barcode='+encodeURIComponent(code));if(own!==scanGeneration||props.disabled)return;if(data.items?.length){emit('choose',data.items[0]);message.value=t('barcodeFound')+' '+displayName(data.items[0],locale.value)}else{emit('manual',code);message.value=t('barcodeUnknown')}scanOpen.value=false}catch(e){if(own===scanGeneration)emit('error',e)}finally{if(own===scanGeneration)scanning.value=false}}
</script>
<template><section class="storage-panel"><h2>{{t('selectWine')}}</h2><button type="button" :disabled="disabled||scanning" @click="scanOpen=!scanOpen">{{t('scanBottle')}}</button><ProductBarcodeScanner v-if="scanOpen" :auto-start="true" :disabled="disabled||scanning" @code="barcode"/><p v-if="scanning" role="status">{{t('loading')}}</p><p v-if="message" class="storage-notice" role="status">{{message}}</p><div class="storage-customer-fields"><label>{{t('wineSearch')}}<input v-model="search" maxlength="120" :placeholder="t('wineSearch')"></label><label>{{t('wineCategory')}}<select v-model="category"><option value="">{{t('allCategories')}}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{displayName(c,locale)}}</option></select></label></div><p v-if="loading" role="status">{{t('loading')}}</p><p v-else-if="!items.length" class="cards-muted">{{t('noProducts')}}</p><div class="storage-wine-rows"><button v-for="p in items" :key="p.id" type="button" :disabled="disabled" @click="emit('choose',p)"><span><strong>{{displayName(p,locale)}}</strong><small>{{p.code}}</small></span><span>{{t('chooseWine')}} ＋</span></button></div><div v-if="page||more" class="cards-actions"><button type="button" :disabled="disabled||loading||!page" @click="page--">{{t('previousPage')}}</button><span>{{t('pageLabel')}} {{page+1}}</span><button type="button" :disabled="disabled||loading||!more" @click="page++">{{t('nextPage')}}</button></div><button type="button" :disabled="disabled" @click="emit('manual','')">{{t('manualWine')}}</button><slot/></section></template>
<style scoped>.storage-wine-rows{display:grid;gap:8px;margin:14px 0}.storage-wine-rows button{display:flex;justify-content:space-between;align-items:center;text-align:left;gap:12px;padding:14px;min-width:0}.storage-wine-rows button>span:first-child{display:grid;gap:4px;min-width:0;overflow-wrap:anywhere}.storage-wine-rows button>span:last-child{white-space:nowrap}.storage-wine-rows small{font-weight:normal;color:#70818a}</style>
